function render(ctx) {
  const w = ctx.data.word;
  const medium = ctx.family === 'medium';

  const header = { type: 'hstack', spacing: 4, children: [
    { type: 'symbol', name: 'book.closed.fill', size: 11, color: '#E0B354' },
    { type: 'text', value: 'Word of the day', size: 11, weight: 'semibold', color: '#E0B354', lineLimit: 1 },
    { type: 'spacer' },
    medium && { type: 'text', value: ctx.today.weekday + ' ' + Number(ctx.today.date.slice(8)),
      size: 11, color: '#8E8A80' },
  ] };

  const body = w
    ? [
        { type: 'text', value: w.word || '', size: medium ? 26 : 22, weight: 'bold', design: 'serif',
          color: '#F5F1E8', lineLimit: 1, minScale: 0.5 },
        { type: 'text', value: w.kind || '', size: 11, italic: true, color: '#B8B2A6', lineLimit: 1 },
        { type: 'text', value: w.definition || '', size: 12, color: '#E6E1D6', lineLimit: medium ? 2 : 3 },
        medium && w.example && { type: 'text', value: '"' + w.example + '"', size: 11, italic: true,
          color: '#B8B2A6', lineLimit: 1 },
      ]
    : [
        { type: 'spacer' },
        { type: 'text', value: 'Your first word', size: medium ? 26 : 22, weight: 'bold', design: 'serif',
          color: '#F5F1E8', lineLimit: 1, minScale: 0.5 },
        { type: 'text', value: 'arrives at 6:00 in the morning.', size: 12, color: '#B8B2A6', lineLimit: 2 },
      ];

  return {
    type: 'vstack', align: 'leading', spacing: 4, padding: 14,
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
    widgetBackground: '#1F1B16',
    children: [header].concat(body),
  };
}
